window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-938e4cb87368392d"]={"versions": [{"id": "FIG-938e4cb87368392d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition zur E2E-Bibliothek (AUTOSAR Classic Platform). Das Diagramm spezifiziert die Struktur <code>E2E_P22ProtectStateType</code> innerhalb des Namensraums <code>E2E::E2E_P22Types</code> als Zustandsdatenstruktur für den Sender-Schutzmechanismus des E2E-Profils 22.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein einzelnes Strukturelement mit Stereotyp <code>«structure»</code>:</p>\n<ul class=\"fig-list\"><li>Typ: <code>E2E::E2E_P22Types::E2E_P22ProtectStateType</code>\n</li><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ Counter :uint8</code> (öffentliches Zustandsfeld für den Sequenz- bzw. Sendezähler, Basistyp <code>uint8</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne Verhaltens- oder Sequenzdarstellung. Die Struktur dient als Ein-/Ausgangs-Zustandsparameter (<code>inout</code>) für die Funktion <code>E2E_P22Protect()</code>, in der <code>Counter</code> bei jedem Aufruf inkrementiert und im Datenstrom serialisiert wird, um Nachrichtenverluste oder Wiederholungen empfängerseitig erkennbar zu machen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition einer C-Struktur für Implementierer der AUTOSAR E2E Library Profile 22. Der Zustandsspeicher muss vom Aufrufer persistent über aufeinanderfolgende Schutzzyklen hinweg vorgehalten und initialisiert werden. <code>Counter</code> definiert den aktuellen Zählerstand mit Wertebereich gemäß <code>uint8</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-619d3de887a6d0a0", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition zur E2E-Bibliothek (AUTOSAR Classic Platform). Das Diagramm spezifiziert die Struktur <code>E2E_P22ProtectStateType</code> innerhalb des Pakets <code>E2E_P22Types</code> als Zustandsdatenstruktur für den Sender-Schutzmechanismus des E2E-Profils 22.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein einzelnes Strukturelement mit Stereotyp <code>«structure»</code>:</p>\n<ul class=\"fig-list\"><li>Typ: <code>E2E_P22Types::E2E_P22ProtectStateType</code>\n</li><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ Counter: uint8</code> (öffentliches Zustandsfeld für den Sequenz- bzw. Sendezähler, Basistyp <code>uint8</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne Verhaltens- oder Sequenzdarstellung. Die Struktur dient als Ein-/Ausgangs-Zustandsparameter (<code>inout</code>) für die Funktion <code>E2E_P22Protect()</code>, in der <code>Counter</code> bei jedem Aufruf inkrementiert und im Datenstrom serialisiert wird, um Nachrichtenverluste oder Wiederholungen empfängerseitig erkennbar zu machen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition einer C-Struktur für Implementierer der AUTOSAR E2E Library Profile 22. Der Zustandsspeicher muss vom Aufrufer persistent über aufeinanderfolgende Schutzzyklen hinweg vorgehalten und initialisiert werden. <code>Counter</code> definiert den aktuellen Zählerstand mit Wertebereich gemäß <code>uint8</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-02642191cd486c4b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition zur E2E-Bibliothek (AUTOSAR Classic Platform). Das Diagramm spezifiziert die Struktur <code>E2E_P22ProtectStateType</code> innerhalb des Pakets <code>E2E_P22Types</code> als Zustandsdatenstruktur für den Sender-Schutzmechanismus des E2E-Profils 22.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein einzelnes Strukturelement mit Stereotyp <code>«structure»</code>:</p>\n<ul class=\"fig-list\"><li>Typ: <code>E2E_P22Types::E2E_P22ProtectStateType</code>\n</li><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ Counter: uint8</code> (öffentliches Zustandsfeld für den Sequenz- bzw. Sendezähler, Basistyp <code>uint8</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne Verhaltens- oder Sequenzdarstellung. Die Struktur dient als Ein-/Ausgangs-Zustandsparameter (<code>inout</code>) für die Funktion <code>E2E_P22Protect()</code>, in der <code>Counter</code> bei jedem Aufruf inkrementiert und im Datenstrom serialisiert wird, um Nachrichtenverluste oder Wiederholungen empfängerseitig erkennbar zu machen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition einer C-Struktur für Implementierer der AUTOSAR E2E Library Profile 22. Der Zustandsspeicher muss vom Aufrufer persistent über aufeinanderfolgende Schutzzyklen hinweg vorgehalten und initialisiert werden. <code>Counter</code> definiert den aktuellen Zählerstand mit Wertebereich gemäß <code>uint8</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-938e4cb87368392d", "to": "FIG-619d3de887a6d0a0", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>«structure» E2E::E2E_P22Types::E2E_P22ProtectStateType</code>: Paketpräfix <code>E2E::</code> im qualifizierten Typnamen entfernt zu <code>E2E_P22Types::E2E_P22ProtectStateType</code>.\n</li><li><code>+ Counter :uint8</code>: Typannotation redaktionell formatiert von <code> :uint8</code> zu <code>: uint8</code> (Leerzeichen vor den Doppelpunkt entfernt, Leerzeichen nach dem Doppelpunkt ergänzt).\n</li></ul>"}, {"from": "FIG-619d3de887a6d0a0", "to": "FIG-02642191cd486c4b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
